using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class SectionsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Sections", "View"); return AdminDataService.GetList("Sections"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Sections", "View"); return AdminDataService.GetDefinitionMetadata("Sections"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Sections", "Delete"); return AdminDataService.Delete("Sections", id); } } }
